<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';
import Button from 'primevue/button'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Checkbox from 'primevue/checkbox'; import Message from 'primevue/message';
const step=ref(1), sample=ref(0), fileInput=ref<HTMLInputElement|null>(null), dragging=ref(false);
const worlds=[{name:'Лес',title:'Волшебный лес',icon:'pi-sparkles',text:'Тайные тропинки и необыкновенные друзья',color:'forest'},{name:'Космос',title:'Среди звёзд',icon:'pi-star',text:'Далёкие планеты и большие открытия',color:'space'},{name:'Море',title:'Тайны океана',icon:'pi-compass',text:'Сокровища глубин и смелые путешествия',color:'sea'}];
const samples=[{title:'Книга, которая светилась',text:'На краю леса, там, где засыпает ветер, маленький путешественник нашёл необычную книгу. Её страницы тихонько светились. «Я ждал тебя», — прошептал лисёнок.'},{title:'По ту сторону тропинки',text:'За деревьями мерцали огоньки уютного домика. Лисёнок взмахнул хвостом: «Самые удивительные истории начинаются с первого шага». И друзья отправились навстречу чудесам.'}];
function newStory(){oid.value='';form.value={name:'',age:5,theme:'Лес',interests:'',consent:false};photo.value=false;step.value=1;if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';page.value='form'}
function resume(o:any){oid.value=o.id;form.value={...o.profile};step.value=1;photo.value=false;if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';page.value='form'}
async function next(){if(!form.value.name.trim()){error.value='Подскажите, как зовут героя';return}await act(async()=>{if(token.value)await save();step.value++})}
const tg=(window as any).Telegram?.WebApp;
const token=ref(''), error=ref(''), busy=ref(false), orders=ref<any[]>([]), page=ref('home'), oid=ref(''), photo=ref(false), preview=ref('');
const form=ref({name:'',age:5,theme:'Лес',interests:'',consent:false});
let timer:ReturnType<typeof setTimeout>;
async function api(path:string, options:RequestInit={}){
 const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);
 try{
  let r:Response;
  try{r=await fetch('/api'+path,{...options,signal:controller.signal,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),Authorization:'Bearer '+token.value,...options.headers}})}
  catch{throw Error('Не удалось связаться с сервером. Проверьте соединение и попробуйте ещё раз.')}
  const isJson=(r.headers.get('content-type')||'').includes('application/json');
  if(!r.ok){
   let detail='';if(isJson){try{const body=await r.json();if(typeof body.detail==='string')detail=body.detail}catch{}}
   if(r.status>=500)throw Error('Сервис временно недоступен. Попробуйте ещё раз через минуту.');
   throw Error(detail||'Не удалось выполнить действие. Попробуйте ещё раз.');
  }
  if(!path.endsWith('/pdf')){
   if(!isJson)throw Error('Сервер вернул неожиданный ответ. Откройте приложение заново через бота.');
   try{await r.clone().json()}catch{throw Error('Ответ сервера загрузился не полностью. Попробуйте ещё раз.')}
  }
  return r;
 }finally{clearTimeout(timeout)}
}
async function act(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function refresh(){orders.value=await (await api('/orders')).json()}
async function save(){const r=await api('/orders'+(oid.value?'/'+oid.value:''),{method:oid.value?'PUT':'POST',body:JSON.stringify(form.value)});oid.value=(await r.json()).id}
async function uploadFile(file?:File){if(!file || busy.value)return;if(!['image/jpeg','image/png'].includes(file.type)){error.value='Выберите фотографию JPEG или PNG';return}if(file.size>8*1024*1024){error.value='Фотография должна быть меньше 8 МБ';return}await act(async()=>{await save();const d=new FormData();d.append('file',file);await api('/orders/'+oid.value+'/photo',{method:'POST',body:d});photo.value=true;if(preview.value)URL.revokeObjectURL(preview.value);preview.value=URL.createObjectURL(file)})}
async function upload(e:Event){const input=e.target as HTMLInputElement;await uploadFile(input.files?.[0]);input.value=''}
async function drop(e:DragEvent){dragging.value=false;await uploadFile(e.dataTransfer?.files[0])}
async function generate(){await act(async()=>{await save();await api('/orders/'+oid.value+'/generate',{method:'POST'});await refresh();page.value='library';oid.value='';photo.value=false})}
async function download(id:string){await act(async()=>{const r=await api('/orders/'+id+'/pdf');const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='skazka-demo.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)})}
async function remove(id:string){if(!confirm('Удалить заказ и все его файлы?'))return;await act(async()=>{await api('/orders/'+id,{method:'DELETE'});await refresh()})}
const labels:Record<string,string>={draft:'Черновик',queued:'В очереди',composing:'Собираем книгу',ready:'Готово',needs_attention:'Нужна помощь'};
onMounted(async()=>{tg?.ready();tg?.expand();if(!tg?.initData)return;await act(async()=>{token.value=(await (await api('/auth',{method:'POST',body:JSON.stringify({init_data:tg.initData})})).json()).token;await refresh()});const poll=async()=>{try{if(token.value)await refresh()}catch{}timer=setTimeout(poll,5000)};timer=setTimeout(poll,5000)});
onUnmounted(()=>{clearTimeout(timer);if(preview.value)URL.revokeObjectURL(preview.value)});
</script>
<template>
<main>
<header><a class="brand" href="#" @click.prevent="page='home'"><span class="brand-icon">✦</span><span>Сказка<small>с тобой</small></span></a><Button label="Мои сказки" icon="pi pi-book" text @click="page='library'"/></header>
<div class="demo-note"><span></span> Открытая демоверсия <span class="note-detail">· бесплатно, без оплаты и ИИ-генерации</span></div>
<Message v-if="error" severity="error" class="error" role="alert">{{error}}</Message>
<template v-if="page==='home'">
<section class="hero">
<div class="hero-copy"><span class="eyebrow">ДЛЯ МАЛЕНЬКИХ ГЕРОЕВ И БОЛЬШИХ МЕЧТ</span><h1>Однажды в сказке<br>оказался <em>ваш ребёнок.</em></h1><p>А дальше — удивительные встречи, смелые открытия и история, которую хочется читать вместе.</p><Button label="Начать мою сказку" icon="pi pi-arrow-right" iconPos="right" size="large" @click="newStory"/><a class="example-link" href="#example">Заглянуть в книгу <i class="pi pi-arrow-down"/></a><div class="hero-facts"><span><i class="pi pi-book"/> 10 страниц</span><span><i class="pi pi-palette"/> 10 иллюстраций</span><span><i class="pi pi-heart"/> Один главный герой</span></div></div>
<div class="hero-art"><picture><source media="(min-width: 601px)" srcset="/images/forest-story.webp"/><img src="/images/forest-story-mobile.webp" alt="Ребёнок и лисёнок читают сияющую книгу в волшебном лесу" fetchpriority="high" decoding="async" width="1672" height="941"/></picture><div class="art-caption"><span>✦</span><div>Здесь начинаются чудеса<small>Иллюстрация-концепт будущей сказки</small></div></div><span class="floating-star" aria-hidden="true">✧</span></div>
</section>
<section class="journey"><div><span>01</span><p><strong>Познакомимся с героем</strong><small>Имя, возраст и любимые занятия</small></p></div><div><span>02</span><p><strong>Выберем приключение</strong><small>Мир, в который хочется отправиться</small></p></div><div><span>03</span><p><strong>Откроем свою книгу</strong><small>Сохраним PDF и прочитаем вместе</small></p></div></section>
<section id="example" class="example-section"><div class="section-heading"><span class="eyebrow">ЗАГЛЯНЕМ МЕЖДУ СТРОК</span><h2>Маленькое окно<br>в большой сказочный мир</h2><p>Концепт оформления. Демонстрационный PDF пока использует более простые рисунки и шаблонный текст.</p></div><div class="storybook"><div class="story-image"><img src="/images/forest-story-mobile.webp" alt="Волшебный лес" loading="lazy" :class="{shifted:sample===1}"/></div><div class="story-page"><span class="eyebrow">ГЛАВА {{sample+1}}</span><h3>{{samples[sample].title}}</h3><p>{{samples[sample].text}}</p><span class="page-number">{{sample+1}}</span></div></div><div class="book-controls"><Button icon="pi pi-arrow-left" aria-label="Предыдущий разворот" text rounded :disabled="sample===0" @click="sample--"/><span>{{sample+1}} / {{samples.length}}</span><Button icon="pi pi-arrow-right" aria-label="Следующий разворот" text rounded :disabled="sample===samples.length-1" @click="sample++"/></div></section>
<section class="world-section"><div class="section-heading"><span class="eyebrow">У КАЖДОЙ ИСТОРИИ СВОЙ МИР</span><h2>Куда зовёт воображение?</h2></div><div class="world-grid"><button v-for="w in worlds" :key="w.name" class="world-card" :class="w.color" @click="newStory();form.theme=w.name"><span class="world-orbit" aria-hidden="true"><i :class="['pi',w.icon]"/></span><span class="world-copy"><strong>{{w.title}}</strong><small>{{w.text}}</small></span><i class="pi pi-arrow-up-right"/></button></div><p class="fineprint">В демоверсии тема сохраняется в анкете; сюжет пока общий для всех миров.</p></section>
<section class="closing"><span>✦</span><h2>Самые тёплые истории —<br>те, что вы читаете вместе.</h2><Button label="Создать первую сказку" icon="pi pi-arrow-right" iconPos="right" @click="newStory"/></section>
</template>
<section v-else-if="!token" class="panel telegram-panel"><i class="pi pi-send"/><span class="eyebrow">ВАША ИСТОРИЯ УЖЕ БЛИЗКО</span><h1>Продолжим в Telegram</h1><p>Откройте приложение через бота, чтобы сохранить свою сказку и получить готовую книгу.</p><a class="telegram-link" href="https://t.me/fairytale_test1_bot">Открыть бота <i class="pi pi-arrow-up-right"/></a></section>
<section v-else-if="page==='form'" class="creation"><div class="steps" aria-label="Этапы создания"><span v-for="(label,i) in ['Герой','Фотография','Приключение']" :key="label" :class="{active:step===i+1,complete:step>i+1}" :aria-current="step===i+1?'step':undefined"><b>{{step>i+1?'✓':i+1}}</b>{{label}}</span></div>
<div class="form-layout"><form class="form-panel" @submit.prevent="step<3?next():generate()"><span class="eyebrow">ШАГ {{step}} ИЗ 3</span><template v-if="step===1"><h1>Кто станет героем?</h1><p>Каждая большая история начинается с одного маленького знакомства.</p><label for="name">Имя ребёнка</label><InputText id="name" v-model="form.name" maxlength="40" required placeholder="Например, Маша" autocomplete="off"/><label for="age">Сколько лет герою?</label><Select inputId="age" v-model="form.age" :options="[3,4,5,6,7,8,9]"/><label for="interests">Что вызывает восторг? <small>Необязательно</small></label><InputText id="interests" v-model="form.interests" maxlength="200" placeholder="Динозавры, звёзды, маленькие котята…"/></template>
<template v-else-if="step===2"><h1>Знакомьтесь, {{form.name}}</h1><p>Добавьте светлое фото, где хорошо видно лицо. В демоверсии оно сохраняется приватно и не используется в рисунках.</p><input ref="fileInput" class="file-input" type="file" accept="image/jpeg,image/png" tabindex="-1" aria-label="Выберите фотографию ребёнка" :disabled="busy" @change="upload"/><div class="upload-zone" :class="{dragging,uploaded:photo}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop"><img v-if="preview" :src="preview" alt="Выбранная фотография ребёнка" class="preview"/><div v-else class="upload-icon"><i class="pi pi-camera"/><span>+</span></div><strong>{{photo?'Вот наш главный герой!':'Добавим немного индивидуальности'}}</strong><span>{{photo?'Фотография загружена':'Выберите фото или перетащите его сюда'}}</span><Button type="button" :label="photo?'Заменить фото':'Выбрать фотографию'" :icon="photo?'pi pi-refresh':'pi pi-image'" :loading="busy" outlined @click="fileInput?.click()"/><small id="photo-help">JPEG или PNG · до 8 МБ</small></div><div class="privacy-note"><i class="pi pi-shield"/><span>Фотографию видите только вы. Удалить её вместе с заказом можно в «Моих сказках».</span></div></template>
<template v-else><h1>Куда отправимся?</h1><p>Выберите мир для маленького большого приключения.</p><div class="world-options" role="group" aria-label="Тема приключения"><button v-for="w in worlds" :key="w.name" type="button" :class="['world-option',w.color,{selected:form.theme===w.name}]" :aria-pressed="form.theme===w.name" @click="form.theme=w.name"><i :class="['pi',w.icon]"/><span><strong>{{w.title}}</strong><small>{{w.text}}</small></span><i :class="['pi',form.theme===w.name?'pi-check-circle':'pi-circle']"/></button></div><div class="demo-explain"><strong>Сейчас создаём бесплатный пример</strong><span>10 страниц с шаблонным текстом и программными рисунками. Тема и интересы пока не меняют сюжет. Оплаты нет.</span></div><div class="consent"><Checkbox inputId="consent" v-model="form.consent" binary/><label for="consent">Я законный представитель ребёнка и согласен на хранение анкеты и фото для демозаказа. Данные можно удалить в «Моих сказках».</label></div></template>
<div class="form-actions"><Button v-if="step>1" label="Назад" text icon="pi pi-arrow-left" :disabled="busy" @click="step--"/><Button type="submit" :label="step===3?'Создать демосказку':'Продолжить'" icon="pi pi-arrow-right" iconPos="right" :loading="busy" :disabled="step===2&&!photo || step===3&&(!photo||!form.consent)"/></div></form><aside class="creation-aside"><img src="/images/forest-story-mobile.webp" alt="Иллюстрация-концепт сказочного леса"/><div><span class="eyebrow">МЕСТО ДЛЯ ВАШЕЙ ИСТОРИИ</span><h2>{{form.name||'Ваш герой'}}<br>и маленькое чудо</h2><p>Одна книга. Десять страниц.<br>Множество поводов обняться.</p><small>Концепт оформления</small></div></aside></div></section>
<section v-else class="library"><div class="library-heading"><div><span class="eyebrow">ВАША КНИЖНАЯ ПОЛКА</span><h1>Истории, которые остаются</h1></div><Button label="Новая сказка" icon="pi pi-plus" @click="newStory"/></div><div v-if="!orders.length" class="empty-library"><i class="pi pi-book"/><h2>Здесь поселится первая сказка</h2><p>Начните с имени — дальше будет волшебство.</p><Button label="Создать сказку" @click="newStory"/></div><div class="library-grid"><article v-for="o in orders" :key="o.id" class="library-book"><div class="cover"><img src="/images/forest-story-mobile.webp" alt="Декоративная обложка"/><div><small>СКАЗКА С ТОБОЙ</small><h2>{{o.profile.name}}<br>и мир чудес</h2><span>{{o.profile.theme}} · демо</span></div></div><div class="book-info"><span class="status" :class="{ready:o.status==='ready'}">{{labels[o.status]||o.status}}</span><p v-if="o.error">{{o.error}}</p><div class="actions"><Button v-if="o.status==='ready'" label="В Telegram" icon="pi pi-send" :disabled="busy" @click="act(async()=>{await api('/orders/'+o.id+'/deliver',{method:'POST'})})"/><Button v-if="o.status==='ready'" icon="pi pi-download" aria-label="Скачать PDF" outlined @click="download(o.id)"/><Button v-if="o.status==='draft'" label="Продолжить" @click="resume(o)"/><Button icon="pi pi-trash" aria-label="Удалить сказку" text severity="secondary" @click="remove(o.id)"/></div></div></article></div></section>
<footer><a class="brand" href="#" @click.prevent="page='home'">✦ Сказка с тобой</a><span>Для маленьких мечтателей и больших объятий.</span><small>Демонстрационная версия</small></footer>
</main>
</template>
